"use client";

import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

const buttonVariants = cva(
  "focus-visible:border-ring focus-visible:ring-ring/50 aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive dark:aria-invalid:border-destructive/50 rounded-lg border border-transparent bg-clip-padding text-sm font-medium focus-visible:ring-3 aria-invalid:ring-3 [&_svg:not([class*='size-'])]:size-4 group/button inline-flex shrink-0 items-center justify-center whitespace-nowrap transition-all outline-none select-none disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground [a]:hover:bg-primary/80",
        outline:
          "border-border bg-background hover:bg-muted hover:text-foreground dark:bg-input/30 dark:border-input dark:hover:bg-input/50 aria-expanded:bg-muted aria-expanded:text-foreground",
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-secondary/80 aria-expanded:bg-secondary aria-expanded:text-secondary-foreground",
        ghost:
          "hover:bg-muted hover:text-foreground dark:hover:bg-muted/50 aria-expanded:bg-muted aria-expanded:text-foreground",
        destructive:
          "bg-destructive/10 hover:bg-destructive/20 focus-visible:ring-destructive/20 dark:focus-visible:ring-destructive/40 dark:bg-destructive/20 text-destructive focus-visible:border-destructive/40 dark:hover:bg-destructive/30",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default:
          "h-8 gap-1.5 px-2.5 has-data-[icon=inline-end]:pr-2 has-data-[icon=inline-start]:pl-2",
        xs: "h-6 gap-1 rounded-[min(var(--radius-md),10px)] px-2 text-xs in-data-[slot=button-group]:rounded-lg has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5 [&_svg:not([class*='size-'])]:size-3",
        sm: "h-7 gap-1 rounded-[min(var(--radius-md),12px)] px-2.5 text-[0.8rem] in-data-[slot=button-group]:rounded-lg has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5 [&_svg:not([class*='size-'])]:size-3.5",
        lg: "h-9 gap-1.5 px-2.5 has-data-[icon=inline-end]:pr-3 has-data-[icon=inline-start]:pl-3",
        icon: "size-8",
        "icon-xs":
          "size-6 rounded-[min(var(--radius-md),10px)] in-data-[slot=button-group]:rounded-lg [&_svg:not([class*='size-'])]:size-3",
        "icon-sm":
          "size-7 rounded-[min(var(--radius-md),12px)] in-data-[slot=button-group]:rounded-lg",
        "icon-lg": "size-9",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
);

function Button({
  className,
  variant = "default",
  size = "default",
  ...props
}: ButtonPrimitive.Props & VariantProps<typeof buttonVariants>) {
  return (
    <ButtonPrimitive
      data-slot="button"
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    />
  );
}

export { Button, buttonVariants };

import type { ComponentProps } from "react";
import { twMerge } from "tailwind-merge";
import { tv, type VariantProps } from "tailwind-variants";

export const badgeVariants = tv({
  base: [
    "inline-flex items-center rounded-md border px-2.5 py-0.5 text-xs font-medium transition-colors",
    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
  ],

  variants: {
    variant: {
      default:
        "border-transparent bg-primary text-primary-foreground hover:bg-primary/80",

      secondary:
        "border-transparent bg-secondary text-secondary-foreground hover:bg-secondary/80",

      destructive:
        "border-transparent bg-destructive text-white hover:bg-destructive/80",

      outline: "border-border text-foreground bg-transparent",

      ghost: "border-transparent text-foreground bg-transparent hover:bg-muted",

      success: "border-transparent bg-green-500 text-white hover:bg-green-600",

      warning:
        "border-transparent bg-yellow-500 text-black hover:bg-yellow-600",

      info: "border-transparent bg-blue-500 text-white hover:bg-blue-600",

      purple: "border-transparent bg-purple-500 text-white hover:bg-purple-600",

      pink: "border-transparent bg-pink-500 text-white hover:bg-pink-600",

      soft: "border-transparent bg-muted text-muted-foreground",

      outlineSuccess: "border-green-500 text-green-600 bg-transparent",

      outlineWarning: "border-yellow-500 text-yellow-600 bg-transparent",

      outlineInfo: "border-blue-500 text-blue-600 bg-transparent",

      dotted:
        "border border-dashed border-border bg-transparent text-foreground",

      dottedSuccess:
        "border border-dashed border-green-500 text-green-600 bg-transparent",

      dottedWarning:
        "border border-dashed border-yellow-500 text-yellow-600 bg-transparent",

      dottedInfo:
        "border border-dashed border-blue-500 text-blue-600 bg-transparent",
    },
  },

  defaultVariants: {
    variant: "default",
  },
});

export type BadgeProps = ComponentProps<"span"> &
  VariantProps<typeof badgeVariants>;

export function Badge({ className, variant, ...props }: BadgeProps) {
  return (
    <span
      data-slot="badge"
      className={twMerge(badgeVariants({ variant }), className)}
      {...props}
    />
  );
}

import type { ComponentProps } from "react";
import { twMerge } from "tailwind-merge";
import { tv, type VariantProps } from "tailwind-variants";

export const dividerVariants = tv({
  base: "shrink-0 border-border",

  variants: {
    orientation: {
      horizontal: "w-full border-t",
      vertical: "h-full border-l",
    },

    variant: {
      solid: "",
      dashed: "border-dashed",
      dotted: "border-dotted",
    },

    color: {
      default: "border-border",
    },

    size: {
      sm: "border",
      md: "border-2",
      lg: "border-[3px]",
    },
  },

  defaultVariants: {
    orientation: "horizontal",
    variant: "solid",
    color: "default",
    size: "sm",
  },
});

export type DividerProps = ComponentProps<"div"> &
  VariantProps<typeof dividerVariants>;

export function Divider({
  className,
  orientation = "horizontal",
  variant,
  color,
  size,
  ...props
}: DividerProps) {
  const classes = twMerge(
    dividerVariants({ orientation, variant, color, size }),
    className,
  );

  if (orientation === "vertical") {
    return (
      <div
        data-slot="divider"
        data-orientation="vertical"
        className={classes}
        aria-hidden
        {...props}
      />
    );
  }

  return (
    <hr
      data-slot="divider"
      data-orientation="horizontal"
      className={classes}
      aria-hidden
      {...(props as ComponentProps<"hr">)}
    />
  );
}

"use client";

import { AnimatePresence, motion } from "framer-motion";
import { ChevronDown } from "lucide-react";
import * as React from "react";

import { cn } from "@/lib/utils";

type AccordionContextType = {
  openItems: string[];
  toggleItem: (value: string) => void;
};

const AccordionContext = React.createContext<AccordionContextType | null>(null);

export interface AccordionProps extends React.ComponentProps<"div"> {
  children: React.ReactNode;
}

export function Accordion({ children, className, ...props }: AccordionProps) {
  const [openItems, setOpenItems] = React.useState<string[]>([]);

  const toggleItem = React.useCallback((value: string) => {
    setOpenItems((prev) =>
      prev.includes(value) ? prev.filter((i) => i !== value) : [...prev, value],
    );
  }, []);

  const value = React.useMemo(
    () => ({ openItems, toggleItem }),
    [openItems, toggleItem],
  );

  return (
    <AccordionContext.Provider value={value}>
      <div
        data-slot="accordion"
        className={cn("w-full space-y-2", className)}
        {...props}
      >
        {children}
      </div>
    </AccordionContext.Provider>
  );
}

export interface AccordionItemProps extends React.ComponentProps<"div"> {
  value: string;
  children: React.ReactNode;
}

export function AccordionItem({
  value: _value,
  children,
  className,
  ...props
}: AccordionItemProps) {
  return (
    <motion.div
      layout
      data-slot="accordion-item"
      className={cn(
        "overflow-hidden rounded-xl border border-border bg-card",
        className,
      )}
      {...props}
    >
      {children}
    </motion.div>
  );
}

export interface AccordionTriggerProps extends React.ComponentProps<"button"> {
  value: string;
  children: React.ReactNode;
}

export function AccordionTrigger({
  value,
  children,
  className,
  ...props
}: AccordionTriggerProps) {
  const context = React.useContext(AccordionContext);
  if (!context)
    throw new Error("AccordionTrigger must be used within Accordion");

  const isOpen = context.openItems.includes(value);

  const handleKeyDown = React.useCallback(
    (e: React.KeyboardEvent<HTMLButtonElement>) => {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        context.toggleItem(value);
      }
    },
    [context, value],
  );

  return (
    <button
      type="button"
      data-slot="accordion-trigger"
      data-state={isOpen ? "open" : "closed"}
      aria-expanded={isOpen}
      onClick={() => context.toggleItem(value)}
      onKeyDown={handleKeyDown}
      className={cn(
        "flex w-full items-center justify-between px-4 py-2 text-left outline-none transition-colors",
        "focus-visible:ring-2 focus-visible:ring-ring",
        isOpen ? "bg-accent" : "hover:bg-accent",
        className,
      )}
      {...props}
    >
      <div className="flex flex-col">
        <span className="text-sm font-medium text-foreground">{children}</span>
      </div>
      <motion.div
        animate={{ rotate: isOpen ? 180 : 0 }}
        transition={{ type: "spring", stiffness: 260, damping: 20 }}
      >
        <ChevronDown className="size-4 text-muted-foreground" aria-hidden />
      </motion.div>
    </button>
  );
}

export interface AccordionContentProps extends React.ComponentProps<"div"> {
  value: string;
  children: React.ReactNode;
}

export function AccordionContent({
  value,
  children,
  className,
  ...props
}: AccordionContentProps) {
  const context = React.useContext(AccordionContext);
  if (!context)
    throw new Error("AccordionContent must be used within Accordion");

  const isOpen = context.openItems.includes(value);

  return (
    <AnimatePresence initial={false}>
      {isOpen && (
        <motion.div
          layout
          data-slot="accordion-content"
          initial={{ height: 0, opacity: 0 }}
          animate={{ height: "auto", opacity: 1 }}
          exit={{ height: 0, opacity: 0 }}
          transition={{ type: "spring", stiffness: 260, damping: 25 }}
          className={cn("overflow-hidden", className)}
          {...props}
        >
          <div className="bg-accent px-4 pb-4 pt-2 text-sm leading-relaxed text-muted-foreground">
            {children}
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

"use client";

import type { ComponentProps, ReactNode } from "react";
import { twMerge } from "tailwind-merge";
import { tv, type VariantProps } from "tailwind-variants";

import { Button } from "@/components/ui/button";

export const actionBarVariants = tv({
  base: [
    "fixed z-50 flex items-center gap-3 border shadow-lg",
    "backdrop-blur-sm supports-[backdrop-filter]:bg-background/20",
  ],
  variants: {
    placement: {
      bottomCenter: "bottom-6 left-1/2 -translate-x-1/2",
      bottomRight: "bottom-6 right-6 left-auto translate-x-0",
      bottomLeft: "bottom-6 left-6 right-auto translate-x-0",
    },
    tone: {
      default: "border-border bg-surface-raised",
      destructive: "border-destructive/50 bg-destructive/10",
      success: "border-green-500/30 bg-green-500/10",
      warning: "border-yellow-500/30 bg-yellow-500/10",
    },
    size: {
      sm: "rounded-lg px-3 py-2",
      md: "rounded-xl px-4 py-3",
    },
  },
  defaultVariants: {
    placement: "bottomCenter",
    tone: "default",
    size: "md",
  },
});

export interface ActionBarActions {
  onConfirm: () => void;
  onCancel: () => void;
  isLoading?: boolean;
}

type ActionBarPropsBase = ComponentProps<"div"> &
  VariantProps<typeof actionBarVariants> & {
    subject?: string;
    title?: string;
    description?: string;
    icon?: ReactNode;
    ariaLabel?: string;
    cancelLabel?: string;
    confirmLabel?: string;
    confirmLabelLoading?: string;
  };

type ActionBarPropsWithActions = ActionBarPropsBase & {
  actions: ActionBarActions;
  onConfirm?: never;
  onCancel?: never;
  isLoading?: never;
};

type ActionBarPropsLegacy = ActionBarPropsBase & {
  actions?: undefined;
  onConfirm: () => void;
  onCancel: () => void;
  isLoading?: boolean;
};

export type ActionBarProps = ActionBarPropsWithActions | ActionBarPropsLegacy;

export function ActionBar(props: ActionBarProps) {
  const {
    subject,
    title,
    description,
    icon,

    ariaLabel = "Confirmar ação",
    cancelLabel = "Cancelar",
    confirmLabel = "Confirmar",
    confirmLabelLoading = "Processando…",
    className,
    placement,
    tone,
    size,
    ...rest
  } = props;

  const actions: ActionBarActions =
    "actions" in props && props.actions
      ? props.actions
      : {
          onConfirm: props.onConfirm,
          onCancel: props.onCancel,
          isLoading: props.isLoading,
        };

  const isLoading = actions.isLoading ?? false;

  return (
    <>
      {/* 🔥 BACKDROP COM BLUR */}
      <div className="" aria-hidden />

      <div
        data-slot="action-bar"
        role="dialog"
        aria-label={ariaLabel}
        data-loading={isLoading ? "" : undefined}
        className={twMerge(
          actionBarVariants({ placement, tone, size }),
          className,
        )}
        {...rest}
      >
        <div className="flex items-center gap-2 text-sm font-medium text-foreground">
          {icon}

          <div className="flex flex-col">
            <span>
              {title ??
                (subject
                  ? `Confirmar ação em "${subject}"?`
                  : "Tem certeza que deseja continuar?")}
            </span>

            {description && (
              <span className="text-xs text-muted-foreground">
                {description}
              </span>
            )}
          </div>
        </div>

        <div className="flex gap-2">
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={actions.onCancel}
            disabled={isLoading}
          >
            {cancelLabel}
          </Button>

          <Button
            type="button"
            variant={tone === "destructive" ? "destructive" : "default"}
            size="sm"
            onClick={actions.onConfirm}
            disabled={isLoading}
          >
            {isLoading ? confirmLabelLoading : confirmLabel}
          </Button>
        </div>
      </div>
    </>
  );
}

"use client";

import {
  AnimatePresence,
  motion,
  useReducedMotion,
  type HTMLMotionProps,
  type Variants,
} from "framer-motion";
import { MoreHorizontal, X } from "lucide-react";
import {
  createContext,
  useContext,
  type ComponentProps,
  type ReactNode,
} from "react";
import { tv, type VariantProps } from "tailwind-variants";
import { twMerge } from "tailwind-merge";

export const detailPanelVariants = tv({
  base: [
    "w-full max-w-[420px] overflow-hidden rounded-2xl border border-border",
    "bg-card text-card-foreground shadow-xl",
  ],
});

const fadeUp = (delay = 0) =>
  ({
    initial: { opacity: 0, y: 10 },
    animate: { opacity: 1, y: 0 },
    transition: {
      duration: 0.35,
      ease: [0.25, 0.46, 0.45, 0.94] as const,
      delay,
    },
  }) as const;

const listVariants: Variants = {
  hidden: {},
  show: {
    transition: { staggerChildren: 0.055 },
  },
};

const rowItemVariants: Variants = {
  hidden: { opacity: 0, x: -6 },
  show: {
    opacity: 1,
    x: 0,
    transition: { duration: 0.3, ease: "easeOut" },
  },
};

type DetailPanelContextValue = {
  onClose?: () => void;
};

const DetailPanelContext = createContext<DetailPanelContextValue | null>(null);

function useDetailPanelContext() {
  return useContext(DetailPanelContext);
}

export type DetailPanelProps = Omit<HTMLMotionProps<"div">, "children"> &
  VariantProps<typeof detailPanelVariants> & {
    open?: boolean;
    onClose?: () => void;
    children?: ReactNode;
  };

function DetailPanel({
  className,
  open = true,
  onClose,
  children,
  ...motionProps
}: DetailPanelProps) {
  const shouldReduceMotion = useReducedMotion();

  const panelVariants: Variants = {
    hidden: shouldReduceMotion
      ? { opacity: 0 }
      : { opacity: 0, scale: 0.96, y: 8 },
    visible: {
      opacity: 1,
      scale: 1,
      y: 0,
      transition: {
        duration: 0.4,
        ease: [0.16, 1, 0.3, 1] as const,
      },
    },
    exit: shouldReduceMotion
      ? { opacity: 0 }
      : {
          opacity: 0,
          scale: 0.97,
          y: 4,
          transition: { duration: 0.2, ease: "easeIn" },
        },
  };

  return (
    <AnimatePresence>
      {open ? (
        <motion.div
          key="detail-panel"
          variants={panelVariants}
          initial="hidden"
          animate="visible"
          exit="exit"
          data-slot="detail-panel"
          className={twMerge(detailPanelVariants(), className)}
          {...motionProps}
        >
          <DetailPanelContext.Provider value={{ onClose }}>
            {children}
          </DetailPanelContext.Provider>
        </motion.div>
      ) : null}
    </AnimatePresence>
  );
}

function DetailPanelHeader({
  className,
  children,
}: {
  className?: string;
  children?: ReactNode;
}) {
  const ctx = useDetailPanelContext();

  return (
    <motion.div
      {...fadeUp(0)}
      data-slot="detail-panel-header"
      className={twMerge(
        "flex items-center justify-between px-5 pt-5 pb-4",
        className,
      )}
    >
      <span className="text-sm font-semibold tracking-[-0.01em]">{children}</span>
      {ctx?.onClose ? (
        <motion.button
          type="button"
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.92 }}
          onClick={ctx.onClose}
          aria-label="Fechar painel"
          className="flex size-7 items-center justify-center rounded-full text-muted-foreground transition-colors hover:bg-accent hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
        >
          <span className="sr-only">Fechar</span>
          <X className="size-4" strokeWidth={2} aria-hidden="true" />
        </motion.button>
      ) : null}
    </motion.div>
  );
}

function DetailPanelContent({
  className,
  ...props
}: ComponentProps<"div">) {
  return (
    <div
      data-slot="detail-panel-content"
      className={twMerge(
        "mx-5 mb-5 space-y-4 rounded-xl border border-border bg-background p-5",
        className,
      )}
      {...props}
    />
  );
}

function DetailPanelFooter({
  className,
  children,
}: {
  className?: string;
  children?: ReactNode;
}) {
  return (
    <motion.div
      {...fadeUp(0.48)}
      data-slot="detail-panel-footer"
      className={twMerge("flex items-center gap-2 px-5 py-3.5", className)}
    >
      {children}
    </motion.div>
  );
}

function DetailPanelSeparator({ className }: { className?: string }) {
  return (
    <motion.div
      {...fadeUp(0.1)}
      data-slot="detail-panel-separator"
      className={twMerge("h-px bg-border", className)}
    />
  );
}

export type DetailPanelHighlightProps = {
  label?: ReactNode;
  primary: ReactNode;
  secondary?: ReactNode;
  className?: string;
};

function DetailPanelHighlight({
  label,
  primary,
  secondary,
  className,
}: DetailPanelHighlightProps) {
  return (
    <motion.div
      {...fadeUp(0.06)}
      data-slot="detail-panel-highlight"
      className={className}
    >
      {label ? (
        <p className="mb-1 text-[10px] font-medium uppercase tracking-widest text-muted-foreground">
          {label}
        </p>
      ) : null}
      <div className="flex items-baseline gap-0.5">
        <span className="text-[40px] font-semibold leading-none tracking-[-0.03em]">
          {primary}
        </span>
        {secondary ? (
          <span className="text-[22px] font-normal leading-none text-muted-foreground">
            {secondary}
          </span>
        ) : null}
      </div>
    </motion.div>
  );
}

function DetailPanelRows({
  className,
  children,
}: Pick<HTMLMotionProps<"div">, "className" | "children">) {
  return (
    <motion.div
      variants={listVariants}
      initial="hidden"
      animate="show"
      data-slot="detail-panel-rows"
      className={twMerge("space-y-2.5", className)}
    >
      {children}
    </motion.div>
  );
}

export type DetailPanelRowProps = {
  icon?: ReactNode;
  label: ReactNode;
  value: ReactNode;
  className?: string;
};

function DetailPanelRow({
  icon,
  label,
  value,
  className,
}: DetailPanelRowProps) {
  return (
    <motion.div
      variants={rowItemVariants}
      data-slot="detail-panel-row"
      className={twMerge("flex min-w-0 items-center gap-2.5", className)}
    >
      {icon ? (
        <span className="flex w-4 shrink-0 items-center justify-center [&_svg]:size-3.5 [&_svg]:shrink-0 [&_svg]:text-muted-foreground">
          {icon}
        </span>
      ) : null}
      <span className="min-w-0 flex-1 text-[12px] text-muted-foreground">
        {label}
      </span>
      <span className="shrink-0 text-right text-[12px] text-foreground">
        {value}
      </span>
    </motion.div>
  );
}

export type DetailPanelNoteProps = {
  label?: ReactNode;
  children: ReactNode;
  className?: string;
};

function DetailPanelNote({
  label = "Nota",
  children,
  className,
}: DetailPanelNoteProps) {
  return (
    <motion.div
      {...fadeUp(0.35)}
      data-slot="detail-panel-note"
      className={twMerge("space-y-1.5", className)}
    >
      <p className="text-[10px] font-medium uppercase tracking-widest text-muted-foreground">
        {label}
      </p>
      <div className="rounded-xl border border-border bg-muted/30 p-3 text-[12px] leading-relaxed text-muted-foreground">
        {children}
      </div>
    </motion.div>
  );
}

function DetailPanelAttachments({
  className,
  children,
}: ComponentProps<"div">) {
  return (
    <motion.div
      {...fadeUp(0.42)}
      data-slot="detail-panel-attachments"
      className={twMerge("space-y-1.5", className)}
    >
      <p className="text-[10px] font-medium uppercase tracking-widest text-muted-foreground">
        Anexos
      </p>
      {children}
    </motion.div>
  );
}

export type DetailPanelAttachmentProps = {
  name: ReactNode;
  meta?: ReactNode;
  icon?: ReactNode;
  onMenuClick?: () => void;
  className?: string;
};

function DetailPanelAttachment({
  name,
  meta,
  icon,
  onMenuClick,
  className,
}: DetailPanelAttachmentProps) {
  return (
    <motion.div
      className={twMerge(
        "flex min-w-0 cursor-pointer items-center gap-2.5 rounded-xl border border-border bg-muted/20 p-2.5 transition-colors hover:bg-accent",
        className,
      )}
      data-slot="detail-panel-attachment"
    >
      <span className="shrink-0 text-muted-foreground [&_svg]:size-7">
        {icon}
      </span>
      <div className="min-w-0 flex-1">
        <p className="truncate text-[12px] text-foreground/80">{name}</p>
      </div>
      {meta ? (
        <span className="shrink-0 text-[11px] text-muted-foreground">
          {meta}
        </span>
      ) : null}
      {onMenuClick ? (
        <motion.button
          type="button"
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.9 }}
          onClick={(e) => {
            e.stopPropagation();
            onMenuClick();
          }}
          aria-label="Opções do anexo"
          className="flex size-6 shrink-0 items-center justify-center rounded text-muted-foreground transition-colors hover:bg-accent hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
        >
          <span className="sr-only">Mais opções</span>
          <MoreHorizontal
            className="size-4"
            strokeWidth={1.8}
            aria-hidden="true"
          />
        </motion.button>
      ) : null}
    </motion.div>
  );
}

export type DetailPanelFooterActionProps = {
  ariaLabel: string;
  icon: ReactNode;
  onClick?: () => void;
  className?: string;
};

function DetailPanelFooterAction({
  ariaLabel,
  icon,
  onClick,
  className,
}: DetailPanelFooterActionProps) {
  return (
    <motion.button
      type="button"
      whileTap={{ scale: 0.92 }}
      aria-label={ariaLabel}
      onClick={onClick}
      data-slot="detail-panel-footer-action"
      className={twMerge(
        "flex size-8 items-center justify-center rounded-lg bg-accent text-muted-foreground transition-colors hover:bg-accent/80 hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
        className,
      )}
    >
      {icon}
    </motion.button>
  );
}

